const searchResults = $input.all();
const businesses = $('Prepare Search Query').all();

const THIRD_PARTY_DOMAINS = [
  // Registres / informations entreprises
  'societe.com',
  'pappers.fr',
  'verif.com',
  'manageo.fr',
  'entreprises.lefigaro.fr',
  'annuaire-entreprises.data.gouv.fr',
  'infonet.fr',
  'dataprospects.fr',

  // Annuaires
  'annuairelocal.fr',
  'annuairefrancais.fr',
  'saloncoiffure.net',
  'unboncoiffeur.fr',
  'telephone.city',
  'sectorama.fr',
  'eterritoire.fr',
  'guadeloupe.net',
  'icigwada.com',
  'pagesjaunes.fr',
  '118000.fr',
