  'instagram.com',
  'linkedin.com',
  'tiktok.com',
  'twitter.com',
  'x.com',

  // Autres plateformes
  'tripadvisor.fr',
  'tripadvisor.com',
  'yelp.fr',
  'yelp.com',
  'google.com',
  'google.fr'
];

function getHostname(url = '') {
  const value = String(url).trim();

  const match = value.match(/^https?:\/\/([^\/?#]+)/i);

  if (!match) {
    return '';
  }

  return match[1]
    .toLowerCase()
    .replace(/^www\./, '')
    .split(':')[0];
}

function isThirdParty(url) {
  const host = getHostname(url);

  if (!host) {
    return true;
  }

  return THIRD_PARTY_DOMAINS.some(domain =>
    host === domain ||
    host.endsWith('.' + domain)
  );
}

function normalize(text = '') {
  return String(text)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
}

function getTokens(text = '') {
  return String(text)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
    .split(/\s+/)
    .filter(token => token.length >= 4);
}

return searchResults.map((item, index) => {

  const response = item.json;
  const business = businesses[index]?.json || {};

  const businessName =
    business.trade_name ||
    business.legal_name ||
    '';

  const city =
    business.official_address?.city ||
    '';

  const businessTokens = getTokens(businessName);
  const normalizedCity = normalize(city);

  const organic = Array.isArray(response.organic)
    ? response.organic
    : [];

  const evidenceResults = organic.slice(0, 10).map(result => {
    const host = getHostname(result.link);

    const hostNormalized = normalize(host);

    const hostLooksBranded =
      businessTokens.some(token =>
        hostNormalized.includes(token)
      );

    return {
      position: result.position ?? null,
      title: result.title ?? null,
      link: result.link ?? null,
      host,
      is_third_party: isThirdParty(result.link),
      host_looks_branded: hostLooksBranded,
      snippet: result.snippet ?? null
    };
  });

  let candidate = null;

  // ------------------------------------------------
  // 1. WEBSITE FOURNI DIRECTEMENT PAR GOOGLE
  // ------------------------------------------------

  const kgWebsite =
    response.knowledgeGraph?.website || null;

  if (
    kgWebsite &&
    !isThirdParty(kgWebsite)
  ) {
    candidate = {
      url: kgWebsite,
      host: getHostname(kgWebsite),
      reason: 'KNOWLEDGE_GRAPH_OWNED_WEBSITE',
      confidence: 0.97
    };
  }

  // ------------------------------------------------
  // 2. RESULTATS ORGANIQUES
  // ------------------------------------------------

  if (!candidate) {

    for (const result of organic) {

      if (!result.link) {
        continue;
      }

      // Annuaire / plateforme = jamais site propriétaire
      if (isThirdParty(result.link)) {
        continue;
      }

      const host = getHostname(result.link);
      const hostNormalized = normalize(host);

      const hostLooksBranded =
        businessTokens.some(token =>
          hostNormalized.includes(token)
        );

      // Le domaine lui-même doit ressembler au nom du commerce.
      // Cela évite qu'un nouvel annuaire inconnu devienne HAS_WEBSITE.
      if (!hostLooksBranded) {
        continue;
      }

      const text = normalize(
        `${result.title || ''} ${result.snippet || ''}`
      );

      const matchingBusinessTokens =
        businessTokens.filter(token =>
          text.includes(token)
        ).length;

      const businessMatches =
        matchingBusinessTokens >= 1;

      const cityMatches =
        normalizedCity &&
        text.includes(normalizedCity);

      if (
        businessMatches &&
        cityMatches
      ) {
        candidate = {
          url: result.link,
          host,
          reason: 'BRANDED_DOMAIN_NAME_AND_CITY_MATCH',
          confidence: 0.92
        };

        break;
      }
    }
  }

  // ------------------------------------------------
  // SITE PROPRIETAIRE VRAIMENT TROUVE
  // ------------------------------------------------

  if (candidate) {
    return {
      json: {
        business_id: business.id,
        legal_name: business.legal_name,
        trade_name: business.trade_name,
        city,

        website_detection_status: 'HAS_WEBSITE',
        has_website: true,
        website_url: candidate.url,
        website_detection_confidence:
          candidate.confidence,

        website_evidence: {
          query: business.search_query,
          detection_reason: candidate.reason,
          detected_host: candidate.host,
          top_results: evidenceResults
        }
      }
    };
  }

  // ------------------------------------------------
  // SINON : DEUXIEME PASSE OBLIGATOIRE
  // ------------------------------------------------

  return {
    json: {
      business_id: business.id,
      legal_name: business.legal_name,
      trade_name: business.trade_name,
      city,

      website_detection_status: 'UNCERTAIN',
      has_website: null,
      website_url: null,
      website_detection_confidence: 0.40,

      website_evidence: {
        query: business.search_query,
        detection_reason:
          'NO_CONFIRMED_OWNED_WEBSITE_FIRST_PASS',
        top_results: evidenceResults
      }
    }
  };
});

