  'saloncoiffure.net',
  'unboncoiffeur.fr',
  'telephone.city',
  'sectorama.fr',
  'eterritoire.fr',
  'guadeloupe.net',
  'icigwada.com',
  'pagesjaunes.fr',
  '118000.fr',
  'villepratique.fr',
  'meilleurcoiffeur.com',
  'alentoor.fr',
  'capistars.fr',
  'complete-tes-commerces.fr',
  'en-ligne.me',
  'siteartisan.fr',
  'mapcarta.com',
  'tel.fr',

  // Réservation / plateformes
  'nrdv.fr',
  'planity.com',
  'treatwell.fr',
  'booksy.com',
  'fresha.com',
  'salonkee.fr',
  'labonnealternance.apprentissage.beta.gouv.fr',

  // Réseaux sociaux
  'facebook.com',
  'instagram.com',
  'linkedin.com',
  'tiktok.com',
  'twitter.com',
  'x.com',

  // Divers
  'tripadvisor.fr',
  'tripadvisor.com',
  'yelp.fr',
