  const match = value.match(/^https?:\/\/([^\/?#]+)/i);

  if (!match) return '';

  return match[1]
    .toLowerCase()
    .replace(/^www\./, '')
    .split(':')[0];
}

function normalize(text = '') {
  return String(text)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
}

function getTokens(text = '') {
  return String(text)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
    .split(/\s+/)
    .filter(token => token.length >= 4);
}

function isThirdParty(url) {
  const host = getHostname(url);

  if (!host) return true;

  return THIRD_PARTY_DOMAINS.some(domain =>
    host === domain ||
    host.endsWith('.' + domain)
  );
}

return searchResults.map((item, index) => {

  const response = item.json;
  const business = businesses[index]?.json || {};

  const businessName =
    business.trade_name ||
    business.legal_name ||
    '';

  const city =
    business.official_address?.city ||
    business.city ||
    '';

  const businessTokens = getTokens(businessName);
  const normalizedCity = normalize(city);

  const organic = Array.isArray(response.organic)
    ? response.organic
    : [];

  let ownedWebsite = null;
  let unknownRelevantResults = 0;
  let matchingThirdPartyResults = 0;

  const evidence = organic.slice(0, 10).map(result => {

    const host = getHostname(result.link);
    const hostNormalized = normalize(host);

    const hostLooksBranded =
      businessTokens.some(token =>
        hostNormalized.includes(token)
      );

    return {
      position: result.position ?? null,
      title: result.title ?? null,
      link: result.link ?? null,
      host,
      is_third_party: isThirdParty(result.link),
      host_looks_branded: hostLooksBranded,
      snippet: result.snippet ?? null
    };
  });

  // --------------------------------------------------
  // 1. KNOWLEDGE GRAPH
  // --------------------------------------------------

  const kgWebsite =
    response.knowledgeGraph?.website || null;

  if (
    kgWebsite &&
    !isThirdParty(kgWebsite)
  ) {
    ownedWebsite = {
      url: kgWebsite,
      host: getHostname(kgWebsite),
      reason: 'KNOWLEDGE_GRAPH_OWNED_WEBSITE',
      confidence: 0.97
    };
  }

  // --------------------------------------------------
  // 2. RESULTATS ORGANIQUES
  // --------------------------------------------------

  if (!ownedWebsite) {

    for (const result of organic) {

      if (!result.link) continue;

      const host = getHostname(result.link);
      const hostNormalized = normalize(host);

      const text = normalize(
        `${result.title || ''} ${result.snippet || ''}`
      );

      const matchingTokens =
        businessTokens.filter(token =>
          text.includes(token)
        ).length;

      const businessMatches =
        matchingTokens >= 1;

      const cityMatches =
        normalizedCity &&
        text.includes(normalizedCity);

      const relevant =
        businessMatches &&
        cityMatches;

      if (!relevant) {
        continue;
      }

      // Annuaire connu
      if (isThirdParty(result.link)) {
        matchingThirdPartyResults++;
        continue;
      }

      const hostLooksBranded =
        businessTokens.some(token =>
          hostNormalized.includes(token)
        );

      // Domaine inconnu mais qui ne ressemble pas au commerce :
      // on ne le considère PAS comme site officiel.
      if (!hostLooksBranded) {
        unknownRelevantResults++;
        continue;
      }

      // Là seulement on accepte le site.
      ownedWebsite = {
        url: result.link,
        host,
        reason: 'BRANDED_DOMAIN_NAME_AND_CITY_MATCH',
        confidence: 0.92
      };

      break;
    }
  }

  // --------------------------------------------------
  // HAS WEBSITE
  // --------------------------------------------------

  if (ownedWebsite) {
    return {
      json: {
        business_id: business.id,
        legal_name: business.legal_name,
        trade_name: business.trade_name,
        city,

        website_detection_status: 'HAS_WEBSITE',
        has_website: true,
        website_url: ownedWebsite.url,
        website_detection_confidence:
          ownedWebsite.confidence,

        website_evidence: {
          first_pass:
            business.website_evidence || null,

          deep_pass: {
            query: business.deep_search_query,
            detection_reason:
              ownedWebsite.reason,
            detected_host:
              ownedWebsite.host,
            results: evidence
          }
        }
      }
    };
  }

  // --------------------------------------------------
  // DOMAINE INCONNU : ON RESTE PRUDENT
  // --------------------------------------------------

  if (unknownRelevantResults > 0) {
    return {
      json: {
        business_id: business.id,
        legal_name: business.legal_name,
        trade_name: business.trade_name,
        city,

        website_detection_status: 'UNCERTAIN',
        has_website: null,
        website_url: null,
        website_detection_confidence: 0.60,

        website_evidence: {
          first_pass:
            business.website_evidence || null,

          deep_pass: {
            query: business.deep_search_query,
            detection_reason:
              'UNVERIFIED_NON_BRANDED_DOMAIN_FOUND',
            unknown_relevant_results:
              unknownRelevantResults,
            matching_third_party_results:
              matchingThirdPartyResults,
            results: evidence
          }
        }
      }
    };
  }

  // --------------------------------------------------
  // NO WEBSITE
  // --------------------------------------------------

  if (matchingThirdPartyResults >= 2) {
    return {
      json: {
        business_id: business.id,
        legal_name: business.legal_name,
        trade_name: business.trade_name,
        city,

        website_detection_status: 'NO_WEBSITE',
        has_website: false,
        website_url: null,
        website_detection_confidence: 0.85,

        website_evidence: {
          first_pass:
            business.website_evidence || null,

          deep_pass: {
            query: business.deep_search_query,
            detection_reason:
              'ONLY_THIRD_PARTY_RESULTS_AFTER_TWO_SEARCHES',
            matching_third_party_results:
              matchingThirdPartyResults,
            results: evidence
          }
        }
      }
    };
  }

  // --------------------------------------------------
  // PAS ASSEZ DE PREUVES
  // --------------------------------------------------

  return {
    json: {
      business_id: business.id,
      legal_name: business.legal_name,
      trade_name: business.trade_name,
      city,

      website_detection_status: 'UNCERTAIN',
      has_website: null,
      website_url: null,
      website_detection_confidence: 0.55,

      website_evidence: {
        first_pass:
          business.website_evidence || null,

        deep_pass: {
          query: business.deep_search_query,
          detection_reason:
            'INSUFFICIENT_EVIDENCE',
          results: evidence
        }
      }
    }
  };
});

return [
  {
    json: {
      start_deep_pass: true,
      started_at: new Date().toISOString()
    }
  }
];
